parameters.jsCode:
const b = $json.body || {};
const h = $json.headers || {};

let kind = 'ignore';
let valid = false;
let out = {};

if (b.payload) {
  // Button click: form-encoded, body.payload is a JSON string
  try {
    const p = typeof b.payload === 'string' ? JSON.parse(b.payload) : b.payload;
    const a = (p.actions || [])[0] || {};
    let val = {};
    try { val = JSON.parse(a.value || '{}'); } catch (e) {}

    if (p.type === 'block_actions' && a.action_id === 'approve_draft' && p.user && p.user.id) {
      kind = 'click';
      valid = true;

      // Keep the draft, drop the button, add a status line
      const kept = ((p.message && p.message.blocks) || []).filter(x => x.type !== 'actions');
      const approvedBlocks = kept.concat([{
        type: 'context',
        elements: [{ type: 'mrkdwn', text: ':white_check_mark: Approved by <@' + p.user.id + '>. Sending to the customer.' }]
      }]);

      out = {
        user: p.user.id,
        channel: (p.channel && p.channel.id) || (p.container && p.container.channel_id),
        thread_ts: (p.container && p.container.thread_ts) || (p.message && p.message.thread_ts),
        message_ts: p.container && p.container.message_ts,
        reply: '',
        caseId: val.caseId,
        version: val.version,
        response_url: p.response_url,
        approvedBlocks
      };
    }
  } catch (e) {}
} else {
  // Thread reply: Slack event
  const e = b.event || {};
  // The bot's own user ID, supplied by Slack on every event
  const botUserId = ((b.authorizations || []).find(x => x.is_bot) || {}).user_id;

  if (
    b.type === 'event_callback' &&
    e.type === 'message' &&
    !e.bot_id &&
    !e.subtype &&
    e.thread_ts &&
    e.user &&
    e.user !== botUserId &&
    !h['x-slack-retry-num']
  ) {
    kind = 'reply';
    valid = true;
    out = {
      user: e.user,
      channel: e.channel,
      thread_ts: e.thread_ts,
      message_ts: e.ts,
      reply: String(e.text || '').replace(/<@[A-Z0-9]+>/g, '').trim(),
      event_id: b.event_id
    };
  }
}

return { json: { valid, kind, ...out } };

